/**
 * constants.js - 全局常量定义
 * 姿态守护应用的所有配置常量集中管理
 */

/** 姿态标签枚举 */
export const POSTURE = {
  STANDING: 'standing',
  SITTING: 'sitting',
  WALKING: 'walking',
  HAND_RAISE: 'hand_raise',
  FALL: 'fall',
  UNKNOWN: 'unknown'
}

/** 姿态中文名映射 */
export const POSTURE_LABEL = {
  standing: '站立',
  sitting: '坐下',
  walking: '行走',
  hand_raise: '抬手',
  fall: '摔倒',
  unknown: '未知'
}

/** 姿态英文名映射 */
export const POSTURE_LABEL_EN = {
  standing: 'Standing',
  sitting: 'Sitting',
  walking: 'Walking',
  hand_raise: 'Hand Raise',
  fall: 'Fall',
  unknown: 'Unknown'
}

/** 姿态对应颜色 */
export const POSTURE_COLOR = {
  standing: '#4CAF50',
  sitting: '#2196F3',
  walking: '#FF9800',
  hand_raise: '#9C27B0',
  fall: '#F44336',
  unknown: '#757575'
}

/** 采样配置 */
export const SAMPLING = {
  /** 默认采样间隔(ms) */
  DEFAULT_INTERVAL: 40,
  /** 游戏模式采样间隔(ms) - 用于高精度场景 */
  FAST_INTERVAL: 20,
  /** 省电模式采样间隔(ms) */
  SLOW_INTERVAL: 100,
  /** 滑动窗口大小(样本数) */
  WINDOW_SIZE: 50,
  /** 传感器数据维度(加速度3轴) */
  INPUT_DIMS: 3,
  /** 特征维度: 均值+方差+最大值+最小值+过零率 = 5 */
  FEATURE_DIMS: 5
}

/** 模型配置 */
export const MODEL = {
  /** CNN输入特征维度 = WINDOW_SIZE * FEATURE_DIMS_PER_AXIS */
  /** 每轴5个特征(均值/方差/最大/最小/过零率)，3轴共15个特征 */
  INPUT_SIZE: 15,
  /** CNN卷积核大小 */
  CONV_KERNEL_SIZE: 5,
  /** 第一层卷积输出通道数 */
  CONV1_CHANNELS: 8,
  /** 第二层卷积输出通道数 */
  CONV2_CHANNELS: 16,
  /** 全连接隐藏层大小 */
  FC_HIDDEN: 24,
  /** 输出类别数 */
  NUM_CLASSES: 5,
  /** 推理置信度阈值 - 低于此值视为未知 */
  CONFIDENCE_THRESHOLD: 0.4,
  /** 投票平滑窗口大小 */
  SMOOTH_WINDOW: 5
}

/** 功耗管理配置 */
export const POWER = {
  /** 低电量阈值(%) */
  LOW_BATTERY_THRESHOLD: 20,
  /** 低电量时采样间隔(ms) */
  LOW_BATTERY_INTERVAL: 200,
  /** 应用后台后传感器暂停延迟(ms) */
  BACKGROUND_PAUSE_DELAY: 5000,
  /** 空闲超时暂停传感器(ms) - 无姿态变化时 */
  IDLE_TIMEOUT: 30000
}

/** 存储键名 */
export const STORAGE_KEY = {
  /** 历史记录 */
  HISTORY: 'posture_history',
  /** 设置 */
  SETTINGS: 'posture_settings',
  /** 模型权重缓存 */
  MODEL_CACHE: 'posture_model'
}

/** 振动模式 */
export const VIBRATE = {
  /** 摔倒警告振动 - 长震动 */
  FALL_ALERT_MODE: 'long',
  /** 摔倒警告振动次数 */
  FALL_ALERT_COUNT: 3,
  /** 摔倒警告振动时长(ms) */
  FALL_ALERT_DURATION: 500,
  /** 摔倒警告振动间隔(ms) */
  FALL_ALERT_INTERVAL: 300
}

/**
 * sensor-manager.js - IMU传感器管理器
 * 负责加速度计的生命周期管理、数据采集、环形缓冲区
 *
 * OpenVela Sensor API:
 *   import sensor from '@system.sensor'
 *   sensor.subscribeAccelerometer({ interval, callback, fail })
 *   sensor.unsubscribeAccelerometer()
 */

import sensor from '@system.sensor'
import { SAMPLING, POWER } from './constants'

/** 传感器状态枚举 */
const STATE = {
  IDLE: 'idle',
  STARTING: 'starting',
  RUNNING: 'running',
  PAUSING: 'pausing',
  PAUSED: 'paused',
  STOPPING: 'stopping'
}

class SensorManager {
  constructor() {
    /** 当前传感器状态 */
    this._state = STATE.IDLE
    /** 原始数据环形缓冲区 [timestamp, x, y, z] */
    this._buffer = []
    /** 缓冲区最大容量 */
    this._maxBuffer = SAMPLING.WINDOW_SIZE * 2
    /** 当前采样间隔(ms) */
    this._interval = SAMPLING.DEFAULT_INTERVAL
    /** 数据回调函数列表 */
    this._listeners = []
    /** 状态变化回调 */
    this._stateListeners = []
    /** 后台暂停定时器 */
    this._bgTimer = null
    /** 数据丢弃计数(异常检测) */
    this._dropCount = 0
    /** 上一次数据时间戳 */
    this._lastTimestamp = 0
    /** 连续异常计数 */
    this._consecutiveErrors = 0
    /** 最大连续异常次数(超过则停止) */
    this._maxConsecutiveErrors = 10
  }

  /** 获取当前状态 */
  get state() { return this._state }

  /** 是否正在运行 */
  get isRunning() { return this._state === STATE.RUNNING }

  /** 获取最近N条原始数据 */
  getData(count) {
    if (count === undefined) count = this._buffer.length
    const start = Math.max(0, this._buffer.length - count)
    return this._buffer.slice(start)
  }

  /** 获取最新的单条数据 { x, y, z } */
  getLatest() {
    if (this._buffer.length === 0) return null
    const last = this._buffer[this._buffer.length - 1]
    return { x: last[1], y: last[2], z: last[3] }
  }

  /** 注册数据监听器 */
  onData(callback) {
    if (typeof callback === 'function') {
      this._listeners.push(callback)
    }
    return () => {
      this._listeners = this._listeners.filter(cb => cb !== callback)
    }
  }

  /** 注册状态变化监听器 */
  onStateChange(callback) {
    if (typeof callback === 'function') {
      this._stateListeners.push(callback)
    }
    return () => {
      this._stateListeners = this._stateListeners.filter(cb => cb !== callback)
    }
  }

  /** 启动传感器采集 */
  start(interval) {
    if (this._state === STATE.RUNNING || this._state === STATE.STARTING) {
      console.log('[SensorManager] 已在运行或启动中, 跳过')
      return
    }

    this._setState(STATE.STARTING)
    this._interval = interval || this._interval
    this._buffer = []
    this._consecutiveErrors = 0

    console.log('[SensorManager] 启动加速度计, interval=' + this._interval + 'ms')

    sensor.subscribeAccelerometer({
      interval: this._getIntervalMode(),
      callback: (data) => {
        this._onData(data)
      },
      fail: (data, code) => {
        console.error('[SensorManager] 订阅失败 code=' + code + ' data=' + data)
        this._consecutiveErrors++
        if (this._consecutiveErrors >= this._maxConsecutiveErrors) {
          console.error('[SensorManager] 连续异常过多, 停止采集')
          this.stop()
        }
      }
    })

    this._setState(STATE.RUNNING)
  }

  /** 停止传感器采集 */
  stop() {
    if (this._state === STATE.IDLE || this._state === STATE.STOPPING) {
      return
    }

    this._setState(STATE.STOPPING)
    console.log('[SensorManager] 停止加速度计')

    try {
      sensor.unsubscribeAccelerometer()
    } catch (e) {
      console.error('[SensorManager] 取消订阅异常: ' + e)
    }

    this._clearBgTimer()
    this._setState(STATE.IDLE)
  }

  /** 暂停采集(后台) */
  pause() {
    if (this._state !== STATE.RUNNING) return

    this._setState(STATE.PAUSING)
    console.log('[SensorManager] 暂停传感器(后台)')

    try {
      sensor.unsubscribeAccelerometer()
    } catch (e) {
      console.error('[SensorManager] 暂停异常: ' + e)
    }

    this._setState(STATE.PAUSED)
  }

  /** 恢复采集(前台) */
  resume() {
    if (this._state !== STATE.PAUSED) return

    console.log('[SensorManager] 恢复传感器(前台)')
    this.start()
  }

  /** 动态调整采样频率 */
  setInterval(interval) {
    if (interval === this._interval) return
    this._interval = interval
    if (this._state === STATE.RUNNING) {
      // 重启传感器以应用新频率
      this.stop()
      this.start(interval)
    }
  }

  /** 切换到省电模式(低采样率) */
  enablePowerSave() {
    this.setInterval(SAMPLING.SLOW_INTERVAL)
  }

  /** 恢复正常采样率 */
  disablePowerSave() {
    this.setInterval(SAMPLING.DEFAULT_INTERVAL)
  }

  /** 低电量回调 - 降频 */
  onLowBattery(level) {
    if (level <= POWER.LOW_BATTERY_THRESHOLD) {
      console.log('[SensorManager] 电量低(' + level + '%), 切换省电模式')
      this.enablePowerSave()
    }
  }

  /** 应用进入后台 - 延迟暂停 */
  onBackground() {
    this._clearBgTimer()
    this._bgTimer = setTimeout(() => {
      if (this._state === STATE.RUNNING) {
        this.pause()
      }
    }, POWER.BACKGROUND_PAUSE_DELAY)
  }

  /** 应用回到前台 - 恢复 */
  onForeground() {
    this._clearBgTimer()
    if (this._state === STATE.PAUSED) {
      this.resume()
    }
  }

  /** 清除后台定时器 */
  _clearBgTimer() {
    if (this._bgTimer !== null) {
      clearTimeout(this._bgTimer)
      this._bgTimer = null
    }
  }

  /** 处理传感器原始数据 */
  _onData(data) {
    const now = Date.now()

    // 异常时间戳检测(跳过过快的数据)
    if (this._lastTimestamp > 0 && (now - this._lastTimestamp) < 5) {
      this._dropCount++
      return
    }

    // NaN检测
    if (isNaN(data.x) || isNaN(data.y) || isNaN(data.z)) {
      this._consecutiveErrors++
      return
    }

    this._consecutiveErrors = 0
    this._lastTimestamp = now

    // 写入环形缓冲区
    const entry = [now, data.x, data.y, data.z]
    this._buffer.push(entry)

    // 缓冲区满时移除最旧数据(保留最近两倍窗口)
    if (this._buffer.length > this._maxBuffer) {
      this._buffer = this._buffer.slice(this._buffer.length - this._maxBuffer)
    }

    // 通知所有监听器
    for (let i = 0; i < this._listeners.length; i++) {
      try {
        this._listeners[i](data)
      } catch (e) {
        console.error('[SensorManager] 监听器异常: ' + e)
      }
    }
  }

  /** 将采样间隔映射为传感器interval模式 */
  _getIntervalMode() {
    if (this._interval <= 30) return 'game'
    if (this._interval <= 60) return 'normal'
    return 'ui'
  }

  /** 设置状态并通知 */
  _setState(state) {
    if (this._state === state) return
    const old = this._state
    this._state = state
    for (let i = 0; i < this._stateListeners.length; i++) {
      try {
        this._stateListeners[i](state, old)
      } catch (e) {
        console.error('[SensorManager] 状态监听器异常: ' + e)
      }
    }
  }

  /** 销毁 - 释放所有资源 */
  destroy() {
    this.stop()
    this._listeners = []
    this._stateListeners = []
    this._buffer = []
  }
}

// 导出单例
export default new SensorManager()

/**
 * preprocessor.js - 信号预处理模块
 * 负责传感器原始数据的清洗、滤波、特征提取
 *
 * 功能:
 *   1. 异常值检测与过滤
 *   2. IIR低通滤波(去噪)
 *   3. Z-score标准化
 *   4. 时域特征提取(均值/方差/最大/最小/过零率)
 *   5. 加速度幅值计算(用于跌倒检测)
 */

import { SAMPLING } from './constants'

class Preprocessor {
  constructor() {
    /** IIR低通滤波器系数(截止频率~20Hz, 采样率25Hz) */
    this._alpha = 0.2
    /** 滤波后的上一帧值 */
    this._prevFiltered = [0, 0, 0]
    /** Z-score标准化参数 { mean, std } (每轴) */
    this._normParams = {
      mean: [0, 0, 0],
      std: [1, 1, 1]
    }
    /** 是否已初始化标准化参数 */
    this._normReady = false
    /** 滑动窗口数据(用于统计标准化参数) */
    this._calibBuffer = []
    /** 校准所需样本数 */
    this._calibSize = 200
    /** 重力加速度估计(用于去除重力分量) */
    this._gravity = [0, 0, 9.8]
    /** 重力估计的IIR系数(低频) */
    this._gravityAlpha = 0.05
  }

  /**
   * 处理单帧数据, 返回清洗后的 [x, y, z]
   * @param {{x: number, y: number, z: number}} raw - 原始加速度数据
   * @returns {{x, y, z, magnitude}|null} 清洗后数据, 异常时返回null
   */
  process(raw) {
    if (!raw || isNaN(raw.x) || isNaN(raw.y) || isNaN(raw.z)) {
      return null
    }

    // 1. 异常值检测: 加速度幅值应在合理范围 [0, 30] m/s²
    const mag = Math.sqrt(raw.x * raw.x + raw.y * raw.y + raw.z * raw.z)
    if (mag > 30 || mag < 0.1) {
      return null
    }

    // 2. IIR低通滤波(去高频噪声)
    const filtered = this._lowPassFilter(raw)

    // 3. 重力分量估计与去除(得到线性加速度)
    this._updateGravity(filtered)
    const linear = [
      filtered[0] - this._gravity[0],
      filtered[1] - this._gravity[1],
      filtered[2] - this._gravity[2]
    ]

    // 4. 校准阶段: 收集数据用于Z-score参数估计
    if (!this._normReady) {
      this._calibBuffer.push([linear[0], linear[1], linear[2]])
      if (this._calibBuffer.length >= this._calibSize) {
        this._computeNormParams()
      }
      // 校准期间返回原始滤波值(不标准化)
      return {
        x: linear[0],
        y: linear[1],
        z: linear[2],
        magnitude: mag
      }
    }

    // 5. Z-score标准化
    const norm = this._normalize(linear)

    return {
      x: norm[0],
      y: norm[1],
      z: norm[2],
      magnitude: mag
    }
  }

  /**
   * 从滑动窗口数据提取特征向量
   * @param {Array} window - 数据窗口 [[timestamp, x, y, z], ...]
   * @returns {Float32Array} 特征向量 [mean_x, var_x, max_x, min_x, zcr_x, ...]
   */
  extractFeatures(window) {
    const features = new Float32Array(SAMPLING.INPUT_DIMS * SAMPLING.FEATURE_DIMS)

    for (let axis = 0; axis < SAMPLING.INPUT_DIMS; axis++) {
      const col = new Float32Array(window.length)

      // 提取单轴数据
      for (let i = 0; i < window.length; i++) {
        col[i] = window[i][axis + 1] // +1 跳过timestamp
      }

      const base = axis * SAMPLING.FEATURE_DIMS

      // 均值
      features[base] = this._mean(col)
      // 方差
      features[base + 1] = this._variance(col, features[base])
      // 最大值
      features[base + 2] = this._max(col)
      // 最小值
      features[base + 3] = this._min(col)
      // 过零率(相对于均值)
      features[base + 4] = this._zeroCrossingRate(col, features[base])
    }

    return features
  }

  /**
   * 计算加速度幅值(用于跌倒检测辅助判断)
   * @param {Array} window - 数据窗口
   * @returns {{maxMag, avgMag, impactCount}} 幅值统计
   */
  getMagnitudeStats(window) {
    let maxMag = 0
    let sumMag = 0
    let impactCount = 0
    const impactThreshold = 20 // m/s²

    for (let i = 0; i < window.length; i++) {
      const x = window[i][1]
      const y = window[i][2]
      const z = window[i][3]
      const mag = Math.sqrt(x * x + y * y + z * z)

      if (mag > maxMag) maxMag = mag
      sumMag += mag
      if (mag > impactThreshold) impactCount++
    }

    return {
      maxMag: maxMag,
      avgMag: sumMag / window.length,
      impactCount: impactCount
    }
  }

  /**
   * IIR低通滤波
   * @param {Array} raw - [x, y, z]
   * @returns {Array} 滤波后的 [x, y, z]
   */
  _lowPassFilter(raw) {
    const result = [0, 0, 0]
    result[0] = this._alpha * raw.x + (1 - this._alpha) * this._prevFiltered[0]
    result[1] = this._alpha * raw.y + (1 - this._alpha) * this._prevFiltered[1]
    result[2] = this._alpha * raw.z + (1 - this._alpha) * this._prevFiltered[2]
    this._prevFiltered = result.slice()
    return result
  }

  /**
   * 重力分量估计(极低通滤波)
   * @param {Array} filtered - 滤波后的 [x, y, z]
   */
  _updateGravity(filtered) {
    for (let i = 0; i < 3; i++) {
      this._gravity[i] = this._gravityAlpha * filtered[i] + (1 - this._gravityAlpha) * this._gravity[i]
    }
  }

  /**
   * Z-score标准化
   * @param {Array} data - [x, y, z]
   * @returns {Array} 标准化后的 [x, y, z]
   */
  _normalize(data) {
    const result = [0, 0, 0]
    for (let i = 0; i < 3; i++) {
      const std = this._normParams.std[i]
      result[i] = std > 0.001 ? (data[i] - this._normParams.mean[i]) / std : 0
    }
    return result
  }

  /**
   * 从校准缓冲区计算Z-score参数
   */
  _computeNormParams() {
    const n = this._calibBuffer.length
    if (n === 0) return

    for (let axis = 0; axis < 3; axis++) {
      // 计算均值
      let sum = 0
      for (let i = 0; i < n; i++) {
        sum += this._calibBuffer[i][axis]
      }
      const mean = sum / n
      this._normParams.mean[axis] = mean

      // 计算标准差
      let sumSq = 0
      for (let i = 0; i < n; i++) {
        const diff = this._calibBuffer[i][axis] - mean
        sumSq += diff * diff
      }
      const std = Math.sqrt(sumSq / n)
      this._normParams.std[axis] = std > 0.001 ? std : 1
    }

    this._normReady = true
    this._calibBuffer = [] // 释放校准缓冲区
    console.log('[Preprocessor] 校准完成, mean=' + JSON.stringify(this._normParams.mean) +
      ' std=' + JSON.stringify(this._normParams.std))
  }

  // ========== 统计工具函数 ==========

  /** 均值 */
  _mean(arr) {
    let sum = 0
    for (let i = 0; i < arr.length; i++) sum += arr[i]
    return sum / arr.length
  }

  /** 方差 */
  _variance(arr, mean) {
    let sum = 0
    for (let i = 0; i < arr.length; i++) {
      const d = arr[i] - mean
      sum += d * d
    }
    return sum / arr.length
  }

  /** 最大值 */
  _max(arr) {
    let m = arr[0]
    for (let i = 1; i < arr.length; i++) {
      if (arr[i] > m) m = arr[i]
    }
    return m
  }

  /** 最小值 */
  _min(arr) {
    let m = arr[0]
    for (let i = 1; i < arr.length; i++) {
      if (arr[i] < m) m = arr[i]
    }
    return m
  }

  /** 过零率(相对均值) */
  _zeroCrossingRate(arr, mean) {
    let count = 0
    for (let i = 1; i < arr.length; i++) {
      if ((arr[i] - mean) * (arr[i - 1] - mean) < 0) count++
    }
    return count / (arr.length - 1)
  }

  /** 重置(重新校准) */
  reset() {
    this._normReady = false
    this._calibBuffer = []
    this._gravity = [0, 0, 9.8]
    this._prevFiltered = [0, 0, 0]
    console.log('[Preprocessor] 已重置')
  }
}

